insert into categories (id, name, description, "order", color) values
  ('bloco1', 'Execução e Produtividade', 'Avalia a capacidade de transformar planos em entregas concretas, com organização, foco e eficiência. Observa como a pessoa gerencia tempo, prioridades, prazos e volume de trabalho, garantindo constância e qualidade na execução das atividades.', 1, '#6155f5'),
  ('bloco2', 'Qualidade Técnica e Cognitiva', 'Avalia o domínio técnico, a capacidade de raciocínio, análise e resolução de problemas. Considera a atenção aos detalhes, o pensamento lógico e crítico, a clareza intelectual e a aplicação adequada do conhecimento no trabalho.', 2, '#34d399'),
  ('bloco3', 'Relação com Clientes e Stakeholders', 'Avalia como a pessoa se comunica e se relaciona com clientes, parceiros e demais partes envolvidas. Observa empatia, clareza, confiabilidade, postura profissional e a capacidade de compreender necessidades e alinhar expectativas.', 3, '#ff8d28'),
  ('bloco4', 'Relações Internas e Colaboração', 'Avalia a qualidade das relações interpessoais no ambiente interno. Considera trabalho em equipe, comunicação, empatia, disponibilidade para ajudar, respeito às diferenças e contribuição para um clima organizacional saudável.', 4, '#f472b6'),
  ('bloco5', 'Postura Profissional e Ética', 'Avalia atitudes, valores e comportamentos no exercício profissional. Observa responsabilidade, comprometimento, ética, transparência, confiabilidade e coerência entre discurso e prática no dia a dia de trabalho.', 5, '#60a5fa'),
  ('bloco6', 'Desenvolvimento, Adaptação e Futuro', 'Avalia a capacidade de aprender, adaptar-se e evoluir continuamente. Considera abertura a feedbacks, busca por desenvolvimento, flexibilidade diante de mudanças, visão de futuro e disposição para crescer junto com a organização.', 6, '#a78bfa');
